163	VecDBL *spn_collect_pure_translations_from_magnetic_symmetry(
164	    const MagneticSymmetry *sym_msg) {
165	    int i, num_pure_trans;
166	    VecDBL *pure_trans;
167	    VecDBL *ret_pure_trans;
168	    static int identity[3][3] = {{1, 0, 0}, {0, 1, 0}, {0, 0, 1}};
169	    num_pure_trans = 0;
170	    pure_trans = NULL;
171	    ret_pure_trans = NULL;
172	
173	    if ((pure_trans = mat_alloc_VecDBL(sym_msg->size)) == NULL) return NULL;
174	
175	    for (i = 0; i < sym_msg->size; i++) {
176	        /* Take translation with rot=identity and timerev=false */
177	        /* time reversal should be considered for type-IV magnetic space group
178	         */
179	        if (mat_check_identity_matrix_i3(identity, sym_msg->rot[i]) &&
180	            !sym_msg->timerev[i]) {
181	            mat_copy_vector_d3(pure_trans->vec[num_pure_trans],
182	                               sym_msg->trans[i]);
183	            num_pure_trans++;
184	        }
185	    }
186	
187	    /* Shrink allocated size of VecDBL */
188	    if ((ret_pure_trans = mat_alloc_VecDBL(num_pure_trans)) == NULL) {
189	        mat_free_VecDBL(pure_trans);
190	        pure_trans = NULL;
191	        return NULL;
192	    }
193	
194	    for (i = 0; i < num_pure_trans; i++) {
195	        mat_copy_vector_d3(ret_pure_trans->vec[i], pure_trans->vec[i]);
196	    }
197	
198	    mat_free_VecDBL(pure_trans);
199	    pure_trans = NULL;
