659	static int *get_orbits(const int *permutations, const int num_sym,
660	                       const int num_atoms) {
661	    int s, i;
662	    int *equivalent_atoms;
663	
664	    if ((equivalent_atoms = (int *)malloc(sizeof(int) * num_atoms)) == NULL) {
665	        return NULL;
666	    }
667	
668	    for (i = 0; i < num_atoms; i++) {
669	        equivalent_atoms[i] = -1;
670	    }
671	
672	    for (i = 0; i < num_atoms; i++) {
673	        if (equivalent_atoms[i] != -1) {
674	            continue;
675	        }
676	
677	        equivalent_atoms[i] = i;
678	        for (s = 0; s < num_sym; s++) {
679	            equivalent_atoms[permutations[s * num_atoms + i]] = i;
680	        }
681	    }
682	
683	    return equivalent_atoms;
684	}
